# Language metadata for UI
LANGUAGES = [
    {'code': 'en', 'name': 'English', 'native_name': 'English', 'direction': 'ltr', 'flag': '🇬🇧'},
    {'code': 'fa', 'name': 'Persian', 'native_name': 'فارسی', 'direction': 'rtl', 'flag': '🇮🇷'},
    {'code': 'ar', 'name': 'Arabic', 'native_name': 'العربية', 'direction': 'rtl', 'flag': '🇸🇦'},
    {'code': 'ru', 'name': 'Russian', 'native_name': 'Русский', 'direction': 'ltr', 'flag': '🇷🇺'},
    {'code': 'hi', 'name': 'Hindi', 'native_name': 'हिन्दी', 'direction': 'ltr', 'flag': '🇮🇳'},
    {'code': 'es', 'name': 'Spanish', 'native_name': 'Español', 'direction': 'ltr', 'flag': '🇪🇸'},
    {'code': 'zh', 'name': 'Chinese', 'native_name': '中文', 'direction': 'ltr', 'flag': '🇨🇳'},
    {'code': 'de', 'name': 'German', 'native_name': 'Deutsch', 'direction': 'ltr', 'flag': '🇩🇪'},
]

# RTL languages
RTL_LANGUAGES = ['fa', 'ar']

def get_translation(lang_code, key, default=None):
    """Get translation for a key in specified language."""
    if lang_code not in TRANSLATIONS:
        lang_code = 'en'
    translations = TRANSLATIONS.get(lang_code, TRANSLATIONS['en'])
    if key in translations:
        return translations[key]
    if key in TRANSLATIONS['en']:
        return TRANSLATIONS['en'][key]
    return default or key

def get_translations(lang_code):
    """Get all translations for a language."""
    if lang_code not in TRANSLATIONS:
        lang_code = 'en'
    if lang_code == 'en':
        return TRANSLATIONS['en']
    merged = dict(TRANSLATIONS['en'])
    merged.update(TRANSLATIONS.get(lang_code, {}))
    return merged

def is_rtl(lang_code):
    """Check if language is RTL."""
    return lang_code in RTL_LANGUAGES

def get_language_direction(lang_code):
    """Get direction for a language."""
    lang = next((l for l in LANGUAGES if l['code'] == lang_code), None)
    return lang['direction'] if lang else 'ltr'
